// Encrypt archive
void encrypt_archive(const std::string& path, const uint8_t* key) {
    std::ifstream in(path, std::ios::binary);
    std::vector<uint8_t> data((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
    auto encrypted = aes_encrypt(data.data(), data.size());
    std::ofstream out(path + ".enc", std::ios::binary);
    out.write((char*)encrypted.data(), encrypted.size());
    in.close();
    out.close();
    DeleteFileA(path.c_str());
}

// Decrypt archive
void decrypt_archive(const std::string& path, const uint8_t* key) {
    std::ifstream in(path, std::ios::binary);
    std::vector<uint8_t> data((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
    auto decrypted = aes_decrypt(data.data(), data.size());
    std::ofstream out(path.substr(0, path.size() - 4), std::ios::binary);
    out.write((char*)decrypted.data(), decrypted.size());
    in.close();
    out.close();
}

