#pragma once
#include <openssl/evp.h>
#include <vector>
#include <string>

std::vector<uint8_t> aes256_encrypt_gcm(const std::string& plaintext, const std::string& key) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    std::vector<uint8_t> ciphertext(plaintext.size() + 128);
    std::vector<uint8_t> tag(16), iv(12);

    RAND_bytes(iv.data(), 12);

    int len = 0, clen = 0;
    EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, nullptr, nullptr);
    EVP_EncryptInit_ex(ctx, nullptr, nullptr, (const uint8_t*)key.data(), iv.data());
    EVP_EncryptUpdate(ctx, nullptr, &len, (const uint8_t*)plaintext.data(), plaintext.size());
    EVP_EncryptUpdate(ctx, ciphertext.data(), &clen, (const uint8_t*)plaintext.data(), plaintext.size());
    EVP_EncryptFinal_ex(ctx, ciphertext.data() + clen, &len);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag.data());

    EVP_CIPHER_CTX_free(ctx);

    ciphertext.resize(clen + len);
    ciphertext.insert(ciphertext.end(), iv.begin(), iv.end());
    ciphertext.insert(ciphertext.end(), tag.begin(), tag.end());

    return ciphertext;
}
