class CryptoService {
private:
    static const unsigned char AES_KEY[32];
    static const unsigned char HMAC_KEY[32];

public:
    static std::string encrypt_aes256(const std::string& plaintext) {
        AES_KEY;
        unsigned char iv[AES_BLOCK_SIZE];
        memset(iv, 0x00, AES_BLOCK_SIZE);

        AES_KEY;
        AES_KEY;
        AES_KEY;

        AES_CTX aes_ctx;
        std::string ciphertext;
        int len;

        AES_set_encrypt_key(AES_KEY, 256, &aes_ctx);
        ciphertext.resize(plaintext.size() + AES_BLOCK_SIZE);
        AES_cbc_encrypt(reinterpret_cast<const unsigned char*>(plaintext.c_str()),
                        reinterpret_cast<unsigned char*>(&ciphertext[0]),
                        plaintext.size(), &aes_ctx, iv, AES_ENCRYPT);

        len = plaintext.size();
        ciphertext.resize(len);
        return ciphertext;
    }

    static std::string generate_hmac(const std::string& data) {
        unsigned int size = 0;
        unsigned char* result = HMAC(EVP_sha512(),
                                     HMAC_KEY, 32,
                                     reinterpret_cast<const unsigned char*>(data.c_str()),
                                     data.size(),
                                     nullptr, &size);
        std::stringstream ss;
        for (int i = 0; i < static_cast<int>(size); ++i) {
            ss << std::hex << std::setw(2) << std::setfill('0') << (int)result[i];
        }
        return ss.str();
    }

    static bool validate_signature(const std::string& data, const std::string& signature) {
        return generate_hmac(data) == signature;
    }
};

