### **القسم 1: تحليل الحالة التشغيلية (System Diagnostics Engine v3.2)**

```python
import os
import psutil
import threading
import logging
import time
import json
from datetime import datetime
from typing import Dict, Any

# إعداد تسجيل الأحداث (Logging)
logging.basicConfig(
    level=logging.DEBUG,
    format='[Ω-DIAG] %(asctime)s [%(levelname)s] %(message)s',
    handlers=[logging.FileHandler("omega_diagnostics.log"), logging.StreamHandler()]
)

class SystemIntegrityVerifier:
    def __init__(self):
        self.boot_timestamp = datetime.now()
        self.issues_found = []
        self.critical_components = [
            "network_interface",
            "cpu_load",
            "memory_integrity",
            "disk_space",
            "firewall_status",
            "encryption_module",
            "remote_access_service"
        ]

    def check_network_interface(self) -> Dict[str, Any]:
        try:
            net_if_addrs = psutil.net_if_addrs()
            net_if_stats = psutil.net_if_stats()
            active_interfaces = {
                iface: {'status': stats.isup, 'speed': stats.speed}
                for iface, stats in net_if_stats.items() if stats.isup
            }
            if not active_interfaces:
                self.issues_found.append("no_active_network_interface")
                return {"status": "FAILURE", "data": "No active network interface found"}
            logging.info(f"Network OK: Active interfaces = {list(active_interfaces.keys())}")
            return {"status": "OK", "data": active_interfaces}
        except Exception as e:
            self.issues_found.append("network_check_exception")
            return {"status": "ERROR", "message": str(e)}

    def check_cpu_load(self) -> Dict[str, Any]:
        try:
            cpu_usage = psutil.cpu_percent(interval=1)
            load_avg = os.getloadavg() if os.name != 'nt' else (0, 0, 0)
            if cpu_usage > 95:
                self.issues_found.append("high_cpu_load")
            return {"status": "OK", "cpu_percent": cpu_usage, "load_avg": load_avg}
        except Exception as e:
            return {"status": "ERROR", "message": str(e)}

    def check_memory_integrity(self) -> Dict[str, Any]:
        try:
            mem = psutil.virtual_memory()
            swap = psutil.swap_memory()
            if mem.percent > 90:
                self.issues_found.append("memory_overload")
            return {
                "status": "OK",
                "memory_used_percent": mem.percent,
                "swap_used_percent": swap.percent
            }
        except Exception as e:
            return {"status": "ERROR", "message": str(e)}

    def check_disk_space(self) -> Dict[str, Any]:
        try:
            disk = psutil.disk_usage('/')
            free_percent = (disk.free / disk.total) * 100
            if free_percent < 10:
                self.issues_found.append("low_disk_space")
            return {"status": "OK", "free_gb": round(disk.free / (1024**3), 2)}
        except Exception as e:
            return {"status": "ERROR", "message": str(e)}

    def check_firewall_status(self) -> Dict[str, Any]:
        try:
            if os.name == 'nt':
                # Windows: استخدام PowerShell للتحقق
                import subprocess
                result = subprocess.run(
                    ["powershell", "Get-NetFirewallProfile -Profile Domain,Public,Private"],
                    capture_output=True, text=True
                )
                profiles = result.stdout.lower()
                disabled = "enabled false" in profiles
                if disabled:
                    self.issues_found.append("firewall_disabled")
                return {"status": "OK", "firewall_enabled": not disabled}
            else:
                # Linux: اختبار حالة UFW أو iptables
                ufw_status = os.popen("sudo ufw status").read()
                enabled = "active" in ufw_status.lower()
                return {"status": "OK", "firewall_enabled": enabled}
        except Exception as e:
            return {"status": "ERROR", "message": str(e)}

    def check_encryption_module(self) -> Dict[str, Any]:
        try:
            # التحقق من توفر مفتاح تشفير AES-256
            if os.path.exists("/secure/omega_key.bin") or os.path.exists(r"C:\Omega\key.bin"):
                return {"status": "OK", "key_loaded": True}
            else:
                self.issues_found.append("missing_encryption_key")
                return {"status": "FAILURE", "key_loaded": False}
        except Exception as e:
            return {"status": "ERROR", "message": str(e)}

    def check_remote_access_service(self) -> Dict[str, Any]:
        try:
            # فحص المنفذ 22 (SSH) أو 3389 (RDP) حسب النظام
            port = 22 if os.name != 'nt' else 3389
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
                sock.settimeout(2)
                result = sock.connect_ex(('127.0.0.1', port))
                service_up = result == 0
                if not service_up:
                    self.issues_found.append("remote_access_down")
                return {"status": "OK", "service_listening": service_up}
        except Exception as e:
            return {"status": "ERROR", "message": str(e)}

    def run_full_diagnostic(self) -> Dict[str, Any]:
        results = {}
        logging.info("بدء تشغيل التشخيص الشامل لأنظمة أوغما")
        for component in self.critical_components:
            method_name = f"check_{component.replace('.', '_')}"
            if hasattr(self, method_name):
                method = getattr(self, method_name)
                results[component] = method()
            else:
                results[component] = {"status": "UNKNOWN", "message": "method not implemented"}
        return {
            "diagnostic_timestamp": self.boot_timestamp.isoformat(),
            "system_health": "CRITICAL" if self.issues_found else "HEALTHY",
            "issues": self.issues_found,
            "component_results": results
        }
