class AutoRecoveryEngine:
    def __init__(self, diagnostics: SystemIntegrityVerifier):
        self.diagnostics = diagnostics

    def restart_network_stack(self):
        logging.warning("إعادة بناء شبكة الاتصال...")
        if os.name == 'nt':
            os.system("netsh interface ip delete arpcache")
            os.system("ipconfig /release")
            os.system("ipconfig /renew")
            os.system("netsh winsock reset")
            logging.info("إعادة تنفيذ شبكة Windows")
        else:
            os.system("sudo systemctl restart networking")
            logging.info("تمت إعادة تشغيل خدمة الشبكة على Linux")

    def restart_firewall(self):
        if os.name == 'nt':
            os.system("net stop mpssvc && net start mpssvc")
        else:
            os.system("sudo ufw disable && sudo ufw enable")

    def regenerate_encryption_key(self):
        from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
        from cryptography.hazmat.primitives import hashes
        from cryptography.hazmat.backends import default_backend
        import os
        key = os.urandom(32)  # AES-256 Key
        iv = os.urandom(16)
        path = "/secure/omega_key.bin" if os.name != 'nt' else r"C:\Omega\key.bin"
        os.makedirs(os.path.dirname(path), exist_ok=True) if '/' in path else os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as f:
            f.write(key + iv)
        logging.info("تم توليد مفتاح تشفير جديد (AES-256)")

    def fix_issues(self):
        recovery_actions = {
            "no_active_network_interface": self.restart_network_stack,
            "firewall_disabled": self.restart_firewall,
            "missing_encryption_key": self.regenerate_encryption_key,
            "remote_access_down": lambda: logging.warning("يُوصى بتمكين خدمة SSH أو RDP يدويًا")
        }
        for issue in self.diagnostics.issues_found:
            if issue in recovery_actions:
                recovery_actions[issue]()
                logging.info(f"تم معالجة العطل: {issue}")
            else:
                logging.error(f"لا يوجد حل تلقائي للمشكلة: {issue}")
