### **FULL IMPLEMENTATION: ramct_core.c**  
*(C Implementation with POSIX Threads and OpenSSL)*

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/ssl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <time.h>
#include <uuid/uuid.h>
#include <json-c/json.h>
#include <semaphore.h>

#define MAX_SESSIONS 1024
#define MAX_COMMAND_QUEUE 4096
#define AES_KEY_SIZE 32
#define AES_IV_SIZE 12
#define MAX_PAYLOAD_SIZE (1024 * 1024 * 4)  // 4MB
#define LISTEN_PORT 45678
#define HEARTBEAT_INTERVAL_SEC 30

// Global structures
typedef enum {
    SESSION_START,
    SESSION_END,
    COMMAND_EXEC,
    CONFIG_PUSH,
    HEARTBEAT,
    RECONNECT_SIGNAL
} action_type_t;

typedef struct {
    char session_id[37];                // UUID string
    char target_system_id[64];          // Target system identifier
    char start_timestamp[32];           // ISO UTC
    int active;
    int socket_fd;
    unsigned char aes_key[AES_KEY_SIZE];
    unsigned char aes_iv[AES_IV_SIZE];
    time_t last_heartbeat;
    pthread_mutex_t lock;
} session_t;

typedef struct {
    char event_id[37];
    char timestamp_utc[32];
    char *source_ip;                    // malloc'd if present
    action_type_t action;
    char *session_id;                   // malloc'd if present
    char *command;                      // malloc'd for COMMAND_EXEC
    char *target_system_id;             // malloc'd
    char *data_payload_hash;            // SHA-256 hex string
    int verified_channel;
} event_record_t;

typedef struct {
    event_record_t events[MAX_COMMAND_QUEUE];
    int head;
    int tail;
    pthread_mutex_t queue_lock;
    sem_t items;
} event_queue_t;

// Global state
session_t sessions[MAX_SESSIONS];
event_queue_t global_event_queue;
pthread_mutex_t sessions_lock = PTHREAD_MUTEX_INITIALIZER;
SSL_CTX *ssl_ctx;
int server_fd;

// Prototypes
void initialize_ssl();
void* command_dispatcher(void* arg);
void* heartbeat_monitor(void* arg);
void* client_handler(void* arg);
void enqueue_event(event_record_t* event);
event_record_t* dequeue_event();
int decrypt_payload(unsigned char* ciphertext, int ciphertext_len,
                    unsigned char* key, unsigned char* iv,
                    unsigned char** plaintext);
int encrypt_payload(unsigned char* plaintext, int plaintext_len,
                    unsigned char* key, unsigned char* iv,
                    unsigned char** ciphertext);
void log_event_immutably(event_record_t* event);
char* iso8601_timestamp();
void generate_uuid(char* buffer);
int validate_event_schema(json_object* jobj);
action_type_t string_to_action(const char* str);
void broadcast_redundant_state();
void restore_from_persistent_backup();

// Initialization
void initialize_ramct() {
    memset(sessions, 0, sizeof(sessions));
    global_event_queue.head = 0;
    global_event_queue.tail = 0;
    pthread_mutex_init(&global_event_queue.queue_lock, NULL);
    sem_init(&global_event_queue.items, 0, 0);

    initialize_ssl();
    restore_from_persistent_backup();

    // Start background threads
    pthread_t dispatcher, heartbeat;
    pthread_create(&dispatcher, NULL, command_dispatcher, NULL);
    pthread_create(&heartbeat, NULL, heartbeat_monitor, NULL);

    printf("[RAMCT] System initialized. Version 1.8.4.\n");
}

void initialize_ssl() {
    SSL_load_error_strings();
    OpenSSL_add_ssl_algorithms();
    const SSL_METHOD* method = TLS_server_method();
    ssl_ctx = SSL_CTX_new(method);
    if (!ssl_ctx) {
        fprintf(stderr, "[ERROR] Unable to create SSL context\n");
        exit(EXIT_FAILURE);
    }

    // Load cert and key (must be pre-deployed)
    if (SSL_CTX_use_certificate_file(ssl_ctx, "ramct_server.crt", SSL_FILETYPE_PEM) <= 0) {
        fprintf(stderr, "[ERROR] SSL cert load failed\n");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
    if (SSL_CTX_use_PrivateKey_file(ssl_ctx, "ramct_server.key", SSL_FILETYPE_PEM) <= 0) {
        fprintf(stderr, "[ERROR] SSL key load failed\n");
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
    if (!SSL_CTX_check_private_key(ssl_ctx)) {
        fprintf(stderr, "[ERROR] Private key does not match cert\n");
        exit(EXIT_FAILURE);
    }

    SSL_CTX_set_options(ssl_ctx, SSL_OP_NO_SSLv2 | SSL_OP_NO_SSLv3 | SSL_OP_NO_TLSv1 | SSL_OP_NO_TLSv1_1);
    SSL_CTX_set_min_proto_version(ssl_ctx, TLS1_3_VERSION);
}

// Dispatcher thread: process incoming event queue
void* command_dispatcher(void* arg) {
    while (1) {
        sem_wait(&global_event_queue.items);
        event_record_t* event = dequeue_event();
        if (!event) continue;

        // Only react to explicitly provided facts
        switch (event->action) {
            case SESSION_START: {
                pthread_mutex_lock(&sessions_lock);
                int slot = -1;
                for (int i = 0; i < MAX_SESSIONS; i++) {
                    if (!sessions[i].active) {
                        slot = i;
                        break;
                    }
                }
                if (slot == -1) {
                    fprintf(stderr, "[ERROR] No session slot available\n");
                    break;
                }

                generate_uuid(sessions[slot].session_id);
                strncpy(sessions[slot].target_system_id, event->target_system_id, 63);
                strcpy(sessions[slot].start_timestamp, event->timestamp_utc);
                sessions[slot].active = 1;
                sessions[slot].last_heartbeat = time(NULL);
                pthread_mutex_init(&sessions[slot].lock, NULL);

                // Generate new AES-256 session key
                if (RAND_bytes(sessions[slot].aes_key, AES_KEY_SIZE) != 1) {
                    fprintf(stderr, "[ERROR] RNG failure during key gen\n");
                    sessions[slot].active = 0;
                }
                if (RAND_bytes(sessions[slot].aes_iv, AES_IV_SIZE) != 1) {
                    fprintf(stderr, "[ERROR] RNG failure during IV gen\n");
                    sessions[slot].active = 0;
                }

                pthread_mutex_unlock(&sessions_lock);

                // Send session confirmation with key parameters
                // (Key transferred via TLS-protected channel only)
                printf("[SESSION] Started: %s -> %s\n", sessions[slot].session_id, sessions[slot].target_system_id);
                break;
            }
            case COMMAND_EXEC: {
                int found = 0;
                pthread_mutex_lock(&sessions_lock);
                for (int i = 0; i < MAX_SESSIONS; i++) {
                    if (sessions[i].active && strcmp(sessions[i].session_id, event->session_id) == 0) {
                        pthread_mutex_lock(&sessions[i].lock);
                        unsigned char* encrypted;
                        int enc_len;
                        int result = encrypt_payload((unsigned char*)event->command,
                                                    strlen(event->command),
                                                    sessions[i].aes_key,
                                                    sessions[i].aes_iv,
                                                    &encrypted);
                        if (result == 0) {
                            // Send encrypted command over FD (simplified)
                            if (send(sessions[i].socket_fd, encrypted, enc_len, 0) <= 0) {
                                sessions[i].active = 0;
                                printf("[SESSION] Failed command send, dropping session %s\n", sessions[i].session_id);
                            }
                        }
                        pthread_mutex_unlock(&sessions[i].lock);
                        found = 1;
                        break;
                    }
                }
                pthread_mutex_unlock(&sessions_lock);
                if (!found) {
                    printf("[WARN] COMMAND_EXEC for unknown session %s\n", event->session_id);
                }
                break;
            }
            case HEARTBEAT: {
                pthread_mutex_lock(&sessions_lock);
                for (int i = 0; i < MAX_SESSIONS; i++) {
                    if (sessions[i].active && strcmp(sessions[i].session_id, event->session_id) == 0) {
                        sessions[i].last_heartbeat = time(NULL);
                        break;
                    }
                }
                pthread_mutex_unlock(&sessions_lock);
                break;
            }
            case RECONNECT_SIGNAL: {
                // Reconnection logic uses existing session data
                pthread_mutex_lock(&sessions_lock);
                for (int i = 0; i < MAX_SESSIONS; i++) {
                    if (strcmp(sessions[i].session_id, event->session_id) == 0) {
                        sessions[i].active = 1;
                        sessions[i].last_heartbeat = time(NULL);
                        printf("[RECONNECT] Session %s restored\n", sessions[i].session_id);
                        break;
                    }
                }
                pthread_mutex_unlock(&sessions_lock);
                break;
            }
            case SESSION_END:
            case CONFIG_PUSH:
                // Placeholder for future implementation
                break;
        }

        log_event_immutably(event);
        broadcast_redundant_state();
        free(event->source_ip);
        free(event->session_id);
        free(event->command);
        free(event->target_system_id);
        free(event->data_payload_hash);
        free(event);
    }
    return NULL;
}

// Heartbeat monitoring: detect stale sessions
void* heartbeat_monitor(void* arg) {
    while (1) {
        sleep(HEARTBEAT_INTERVAL_SEC);
        time_t now = time(NULL);
        pthread_mutex_lock(&sessions_lock);
        for (int i = 0; i < MAX_SESSIONS; i++) {
            if (sessions[i].active) {
                if (difftime(now, sessions[i].last_heartbeat) > (HEARTBEAT_INTERVAL_SEC * 3)) {
                    printf("[HEARTBEAT] Session %s expired\n", sessions[i].session_id);
                    sessions[i].active = 0;
                    close(sessions[i].socket_fd);
                    pthread_mutex_destroy(&sessions[i].lock);
                }
            }
        }
        pthread_mutex_unlock(&sessions_lock);
    }
    return NULL;
}

// Client socket handler (TLS-wrapped)
void* client_handler(void* arg) {
    int client_fd = *(int*)arg;
    SSL* ssl = SSL_new(ssl_ctx);
    SSL_set_fd(ssl, client_fd);

    if (SSL_accept(ssl) <= 0) {
        ERR_print_errors_fp(stderr);
    } else {
        X509* client_cert = SSL_get_peer_certificate(ssl);
        int verified = (client_cert != NULL);
        if (client_cert) X509_free(client_cert);

        char buffer[MAX_PAYLOAD_SIZE];
        int bytes;
        while ((bytes = SSL_read(ssl, buffer, sizeof(buffer) - 1)) > 0) {
            buffer[bytes] = '\0';
            json_object* jobj = json_tokener_parse(buffer);
            if (!jobj) {
                fprintf(stderr, "[PARSER] Invalid JSON received\n");
                continue;
            }

            if (!validate_event_schema(jobj)) {
                fprintf(stderr, "[VALIDATOR] Schema violation\n");
                json_object_put(jobj);
                continue;
            }

            // Extract to C structure with malloc'd strings
            event_record_t* event = (event_record_t*)malloc(sizeof(event_record_t));
            memset(event, 0, sizeof(event_record_t));

            generate_uuid(event->event_id);
            strcpy(event->timestamp_utc, iso8601_timestamp());

            json_object* tmp;
            if (json_object_object_get_ex(jobj, "source_ip", &tmp)) {
                event->source_ip = strdup(json_object_get_string(tmp));
            }
            if (json_object_object_get_ex(jobj, "action_type", &tmp)) {
                event->action = string_to_action(json_object_get_string(tmp));
            }
            if (json_object_object_get_ex(jobj, "session_id", &tmp)) {
                event->session_id = strdup(json_object_get_string(tmp));
            }
            if (json_object_object_get_ex(jobj, "command", &tmp)) {
                event->command = strdup(json_object_get_string(tmp));
            }
            if (json_object_object_get_ex(jobj, "target_system_id", &tmp)) {
                event->target_system_id = strdup(json_object_get_string(tmp));
            }
            if (json_object_object_get_ex(jobj, "data_payload_hash", &tmp)) {
                event->data_payload_hash = strdup(json_object_get_string(tmp));
            }
            event->verified_channel = verified;

            enqueue_event(event);

            if (event->action == SESSION_START) {
                pthread_mutex_lock(&sessions_lock);
                for (int i = 0; i < MAX_SESSIONS; i++) {
                    if (sessions[i].active && event->target_system_id &&
                        strcmp(sessions[i].target_system_id, event->target_system_id) == 0) {
                        sessions[i].socket_fd = client_fd;
                        break;
                    }
                }
                pthread_mutex_unlock(&sessions_lock);
            }

            json_object_put(jobj);
        }

        SSL_shutdown(ssl);
    }

    SSL_free(ssl);
    close(client_fd);
    free(arg);
    return NULL;
}

// Thread-safe queue operations
void enqueue_event(event_record_t* event) {
    pthread_mutex_lock(&global_event_queue.queue_lock);
    int next = (global_event_queue.head + 1) % MAX_COMMAND_QUEUE;
    if (next == global_event_queue.tail) {
        printf("[QUEUE] Full, dropping oldest event\n");
        global_event_queue.tail = (global_event_queue.tail + 1) % MAX_COMMAND_QUEUE;
    }
    global_event_queue.events[global_event_queue.head] = *event;
    global_event_queue.head = next;
    pthread_mutex_unlock(&global_event_queue.queue_lock);
    sem_post(&global_event_queue.items);
}

event_record_t* dequeue_event() {
    event_record_t* event = (event_record_t*)malloc(sizeof(event_record_t));
    pthread_mutex_lock(&global_event_queue.queue_lock);
    if (global_event_queue.tail == global_event_queue.head) {
        pthread_mutex_unlock(&global_event_queue.queue_lock);
        free(event);
        return NULL;
    }
    *event = global_event_queue.events[global_event_queue.tail];
    global_event_queue.tail = (global_event_queue.tail + 1) % MAX_COMMAND_QUEUE;
    pthread_mutex_unlock(&global_event_queue.queue_lock);
    return event;
}

// AES-256-GCM encryption/decryption
int encrypt_payload(unsigned char* plaintext, int plaintext_len,
                    unsigned char* key, unsigned char* iv,
                    unsigned char** ciphertext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    int len;
    int ciphertext_len;

    if (ctx == NULL) return -1;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL) != 1)
        goto err;
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv) != 1)
        goto err;

    if (EVP_EncryptUpdate(ctx, NULL, &len, NULL, plaintext_len) != 1)
        goto err;
    if (EVP_EncryptUpdate(ctx, *ciphertext = (unsigned char*)malloc(plaintext_len + 16), &ciphertext_len, plaintext, plaintext_len) != 1)
        goto err;
    if (EVP_EncryptFinal_ex(ctx, *ciphertext + ciphertext_len, &len) != 1)
        goto err;
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;

err:
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int decrypt_payload(unsigned char* ciphertext, int ciphertext_len,
                    unsigned char* key, unsigned char* iv,
                    unsigned char** plaintext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    int len;
    int plaintext_len;

    if (ctx == NULL) return -1;

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, NULL, NULL) != 1)
        goto err;
    if (EVP_DecryptInit_ex(ctx, NULL, NULL, key, iv) != 1)
        goto err;

    if (EVP_DecryptUpdate(ctx, *plaintext = (unsigned char*)malloc(ciphertext_len), &plaintext_len, ciphertext, ciphertext_len) != 1)
        goto err;
    if (EVP_DecryptFinal_ex(ctx, *plaintext + plaintext_len, &len) != 1)
        goto err;
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;

err:
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

// Audit logger: write to append-only file
void log_event_immutably(event_record_t* event) {
    FILE *fp = fopen("ramct_audit.jl", "a");  // JSON Lines format
    if (!fp) {
        perror("[AUDIT] Cannot open log file");
        return;
    }

    fprintf(fp, "{\"event_id\":\"%s\",\"timestamp_utc\":\"%s\"", event->event_id, event->timestamp_utc);
    if (event->source_ip) fprintf(fp, ",\"source_ip\":\"%s\"", event->source_ip);
    fprintf(fp, ",\"action_type\":\"");
    switch (event->action) {
        case SESSION_START: fprintf(fp, "session_start"); break;
        case SESSION_END: fprintf(fp, "session_end"); break;
        case COMMAND_EXEC: fprintf(fp, "command_exec"); break;
        case CONFIG_PUSH: fprintf(fp, "config_push"); break;
        case HEARTBEAT: fprintf(fp, "heartbeat"); break;
        case RECONNECT_SIGNAL: fprintf(fp, "reconnect_signal"); break;
    }
    if (event->session_id) fprintf(fp, "\",\"session_id\":\"%s\"", event->session_id);
    if (event->command) fprintf(fp, "\",\"command\":\"%s\"", event->command);
    if (event->target_system_id) fprintf(fp, "\",\"target_system_id\":\"%s\"", event->target_system_id);
    if (event->data_payload_hash) fprintf(fp, "\",\"data_payload_hash\":\"%s\"", event->data_payload_hash);
    fprintf(fp, ",\"verified_channel\":%s}\n", event->verified_channel ? "true" : "false");
    fclose(fp);
}

