### 🔑 Global Encryption & Utilities

```csharp
using System;
using System.Security.Cryptography;
using System.Text;

public static class AesEncryption
{
    private const string Key = "D2D4E8F3A1B5C9F7E2A6D8C1B4E7F9A2D3C5E8F1A6B9D2C7E4F8A1B6D9E2F5A8"; // 256-bit hex key
    private static readonly byte[] KeyBytes = StringToBytes(Key);

    public static string Encrypt(string plainText)
    {
        using var aes = Aes.Create();
        aes.Key = KeyBytes;
        aes.GenerateIV();
        aes.Mode = CipherMode.CBC;
        aes.Padding = PaddingMode.PKCS7;

        using var encryptor = aes.CreateEncryptor();
        byte[] encrypted = encryptor.TransformFinalBlock(Encoding.UTF8.GetBytes(plainText), 0, plainText.Length);
        byte[] result = new byte[aes.IV.Length + encrypted.Length];
        Buffer.BlockCopy(aes.IV, 0, result, 0, aes.IV.Length);
        Buffer.BlockCopy(encrypted, 0, result, aes.IV.Length, encrypted.Length);
        return Convert.ToBase64String(result);
    }

    private static byte[] StringToBytes(string hex)
    {
        var bytes = new byte[hex.Length / 2];
        for (int i = 0; i < bytes.Length; i++)
            bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
        return bytes;
    }
}
