            if (data.Length >= 3 && data[0] == 'v' && data[1] == '1' && data[2] == '0')
                return Encoding.UTF8.GetString(Crypt32Decrypt(data));
            return Encoding.UTF8.GetString(ProtectedData.Unprotect(data, null, DataProtectionScope.LocalMachine));
        }
        catch { return "<decryption_failed>"; }
    }

    [DllImport("crypt32.dll", SetLastError = true, CharSet = CharSet.Auto)]
    private static extern bool CryptUnprotectData(
        ref DATA_BLOB pCipherText,
        ref IntPtr pszDescription,
        ref DATA_BLOB pOptionalEntropy,
        IntPtr pvReserved,
        ref CRYPTPROTECT_PROMPTSTRUCT pPromptStruct,
        int dwFlags,
        ref DATA_BLOB pPlainText);

    private static byte[] Crypt32Decrypt(byte[] encryptedData)
    {
        var cipherBlob = new DATA_BLOB { cbData = encryptedData.Length, pbData = Marshal.AllocHGlobal(encryptedData.Length) };
        var plainBlob = new DATA_BLOB();
        Marshal.Copy(encryptedData, 0, cipherBlob.pbData, encryptedData.Length);

        var prompt = new CRYPTPROTECT_PROMPTSTRUCT();
        var ignored = new DATA_BLOB();

        try
        {
            if (CryptUnprotectData(ref cipherBlob, ref ignored, ref ignored, IntPtr.Zero, ref prompt, 0, ref plainBlob))
            {
                byte[] buffer = new byte[plainBlob.cbData];
                Marshal.Copy(plainBlob.pbData, buffer, 0, plainBlob.cbData);
                return buffer;
            }
            return Array.Empty<byte>();
        }
        finally
        {
            if (cipherBlob.pbData != IntPtr.Zero) Marshal.FreeHGlobal(cipherBlob.pbData);
            if (plainBlob.pbData != IntPtr.Zero) Marshal.FreeHGlobal(plainBlob.pbData);
        }
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    internal struct DATA_BLOB
    {
        public int cbData;
        public IntPtr pbData;
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    internal struct CRYPTPROTECT_PROMPTSTRUCT
