class TaskScheduler {
private:
    std::vector<Task> task_queue;
    std::mutex queue_mutex;
    std::condition_variable cv;
    std::atomic_bool running;
    std::thread scheduler_thread;
    int max_workers;

public:
    TaskScheduler(int workers = 8) : running(false), max_workers(workers) {}

    void Start() {
        running = true;
        scheduler_thread = std::thread(&TaskScheduler::RunLoop, this);
        GetLogger()->Log(LogLevel::INFO, "Scheduler", "Task scheduler started with " + std::to_string(max_workers) + " workers.");
    }

    void Stop() {
        running = false;
        cv.notify_all();
        if (scheduler_thread.joinable()) {
            scheduler_thread.join();
        }
        GetLogger()->Log(LogLevel::INFO, "Scheduler", "Task scheduler stopped.");
    }

    void Submit(Task task) {
        {
            std::lock_guard<std::mutex> lock(queue_mutex);
            task_queue.push_back(task);
        }
        cv.notify_one();
        GetLogger()->Log(LogLevel::DEBUG, "Scheduler", "Task submitted: " + task.id);
    }

private:
    void RunLoop() {
        std::vector<std::thread> workers;
        for (int i = 0; i < max_workers; ++i) {
            workers.emplace_back([this]() {
                while (running) {
                    std::unique_lock<std::mutex> lock(queue_mutex);
                    cv.wait(lock, [this] { return !task_queue.empty() || !running; });

                    if (!running) break;

                    // Sort by priority and creation time
                    std::sort(task_queue.begin(), task_queue.end(), [](const Task& a, const Task& b) {
                        if (a.priority != b.priority) return a.priority > b.priority;
                        return a.created_at < b.created_at;
                    });

                    Task task = task_queue.front();
                    task_queue.erase(task_queue.begin());
                    lock.unlock();

                    try {
                        task.work();
                        GetLogger()->Log(LogLevel::INFO, "Scheduler", "Task completed: " + task.id);
                    } catch (const std::exception& e) {
                        GetLogger()->Log(LogLevel::ERROR, "Scheduler", "Task failed: " + task.id + " - " + e.what());
                    }
                }
            });
        }

        for (auto& w : workers) {
            if (w.joinable()) w.join();
        }
    }
};

class ControlServer {
private:
    int server_fd;
    struct sockaddr_in address;
    std::atomic_bool running;
    std::thread listener_thread;
    std::map<int, std::string> client_buffers;

public:
    ControlServer() : server_fd(-1), running(false) {}

    bool Start(int port) {
        if ((server_fd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0)) == 0) {
            GetLogger()->Log(LogLevel::CRITICAL, "ControlServer", "Failed to create socket.");
            return false;
        }

        int opt = 1;
        if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
            GetLogger()->Log(LogLevel::CRITICAL, "ControlServer", "Failed to set socket options.");
            close(server_fd);
            return false;
        }

        address.sin_family = AF_INET;
        address.sin_addr.s_addr = INADDR_ANY;
        address.sin_port = htons(port);

        if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) < 0) {
            GetLogger()->Log(LogLevel::CRITICAL, "ControlServer", "Socket bind failed.");
            close(server_fd);
            return false;
        }

        if (listen(server_fd, 3) < 0) {
            GetLogger()->Log(LogLevel::CRITICAL, "ControlServer", "Listen failed.");
            close(server_fd);
            return false;
        }

        running = true;
        listener_thread = std::thread(&ControlServer::AcceptLoop, this);
        GetLogger()->Log(LogLevel::INFO, "ControlServer", "Listening on port " + std::to_string(port));
        return true;
    }

    void Stop() {
        running = false;
        if (listener_thread.joinable()) {
            listener_thread.join();
        }
        if (server_fd != -1) {
            close(server_fd);
            server_fd = -1;
        }
        GetLogger()->Log(LogLevel::INFO, "ControlServer", "Control server stopped.");
    }

private:
    void AcceptLoop() {
        std::vector<std::thread> clients;
        fd_set read_fds;
        int max_sd;

        while (running) {
            FD_ZERO(&read_fds);
            FD_SET(server_fd, &read_fds);
            max_sd = server_fd;

            struct timeval timeout{};
            timeout.tv_sec = 1;
            timeout.tv_usec = 0;

            int activity = select(max_sd + 1, &read_fds, NULL, NULL, &timeout);
            if (activity < 0 && errno != EINTR) {
                GetLogger()->Log(LogLevel::ERROR, "ControlServer", "Select error.");
                break;
            }

            if (FD_ISSET(server_fd, &read_fds)) {
                int new_socket;
                struct sockaddr_in client_addr;
                socklen_t addr_len = sizeof(client_addr);
                if ((new_socket = accept(server_fd, (struct sockaddr*)&client_addr, &addr_len)) >= 0) {
                    client_buffers[new_socket] = "";
                    clients.emplace_back([this, new_socket, client_addr]() {
                        HandleClient(new_socket, client_addr);
                    });
                    clients.back().detach();
                }
            }
        }

        for (auto& t : clients) {
            if (t.joinable()) t.join();
        }
    }

    void HandleClient(int sock, struct sockaddr_in& addr) {
        char buffer[MAX_BUFFER_SIZE];
        int bytes_read;

        GetLogger()->Log(LogLevel::INFO, "ControlServer", "Client connected: " + std::string(inet_ntoa(addr.sin_addr)));

        while (running) {
            bytes_read = read(sock, buffer, MAX_BUFFER_SIZE - 1);
            if (bytes_read > 0) {
                buffer[bytes_read] = '\0';
                client_buffers[sock] += std::string(buffer, bytes_read);

                size_t newline;
                while ((newline = client_buffers[sock].find('\n')) != std::string::npos) {
                    std::string cmd = client_buffers[sock].substr(0, newline);
                    client_buffers[sock].erase(0, newline + 1);
                    ProcessCommand(sock, cmd);
                }
            } else if (bytes_read == 0) {
                break;
            } else {
                if (errno != EAGAIN && errno != EWOULDBLOCK) break;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }

        close(sock);
        client_buffers.erase(sock);
        GetLogger()->Log(LogLevel::INFO, "ControlServer", "Client disconnected.");
    }

    void ProcessCommand(int sock, const std::string& cmd) {
        std::string response;

        if (cmd == "STATUS") {
            response = "STATE:RUNNING\nMEM:4GB/16GB\nCPU:34%\nCONNECTIONS:12\n";
        } else if (cmd == "SHUTDOWN") {
            response = "ACK:SHUTDOWN\n";
            SendResponse(sock, response);
            GetSystemController()->TriggerGracefulShutdown();
            return;
        } else if (cmd == "TELEMETRY") {
            TelemetryData td = GetHardwareMonitor()->GetTelemetry();
            std::ostringstream oss;
            oss << "CPU:" << td.cpu_usage_percent << "%\n"
                << "MEM:" << (td.memory_used_kb / 1024) << "MB/" << (td.memory_total_kb / 1024) << "MB\n"
                << "TEMP:" << td.temperature_c << "C\n"
                << "NET_IN:" << (td.network_in_bps / 1000) << "KBps\n"
                << "NET_OUT:" << (td.network_out_bps / 1000) << "KBps\n";
            response = oss.str();
        } else {
            response = "ERROR:UNKNOWN_COMMAND\n";
        }

        SendResponse(sock, response);
    }

    void SendResponse(int sock, const std::string& response) {
        std::string msg = response + "\n";
        send(sock, msg.c_str(), msg.size(), 0);
    }
};

class SystemController {
private:
    SystemState current_state;
    std::atomic_bool shutdown_requested;
    std::mutex state_mutex;
    std::thread heartbeat_thread;
    std::thread telemetry_thread;

public:
    SystemController() : current_state(SystemState::INITIALIZING), shutdown_requested(false) {}

    void Initialize() {
        GetLogger()->Log(LogLevel::INFO, "Controller", "Initializing system components...");
        if (!GetLogger()->file_logging_enabled) {
            GetLogger()->Initialize(LOG_FILE_PATH);
        }
        GetConfig()->LoadFromFile(CONFIG_FILE_PATH);
        GetLogger()->Log(LogLevel::INFO, "Controller", "Configuration loaded.");
        GetTaskScheduler()->Start();
        GetControlServer()->Start(CONTROL_PORT);
        StartHeartbeat();
        StartTelemetryMonitor();
        current_state = SystemState::RUNNING;
        GetLogger()->Log(LogLevel::INFO, "Controller", "System now RUNNING.");
    }

    void TriggerGracefulShutdown() {
        if (shutdown_requested.exchange(true)) return;

        GetLogger()->Log(LogLevel::INFO, "Controller", "Graceful shutdown initiated.");
        current_state = SystemState::SHUTTING_DOWN;

        GetControlServer()->Stop();
        GetTaskScheduler()->Stop();

        if (heartbeat_thread.joinable()) heartbeat_thread.join();
        if (telemetry_thread.joinable()) telemetry_thread.join();

        GetLogger()->Log(LogLevel::INFO, "Controller", "All subsystems terminated.");
        current_state = SystemState::INITIALIZING;
        std::exit(0);
    }

    void StartHeartbeat() {
        heartbeat_thread = std::thread([this]() {
            while (current_state == SystemState::RUNNING) {
                GetLogger()->Log(LogLevel::TRACE, "Heartbeat", "Pulse @ " + std::to_string(std::time(nullptr)));
                std::this_thread::sleep_for(std::chrono::milliseconds(HEARTBEAT_INTERVAL_MS));
            }
        });
    }

    void StartTelemetryMonitor() {
        telemetry_thread = std::thread([this]() {
            while (current_state == SystemState::RUNNING) {
                TelemetryData td = GetHardwareMonitor()->GetTelemetry();
                // In real systems: transmit to monitoring dashboards
                std::this_thread::sleep_for(std::chrono::milliseconds(TELEMETRY_FLUSH_INTERVAL_MS));
            }
        });
    }

    SystemState GetState() const {
        std::lock_guard<std::mutex> lock(state_mutex);
        return current_state;
    }
};

